static const size_t bad_png_n = 61;

static int fails;
static void expect(int cond, const char *msg) {
    if (!cond) { fprintf(stderr, "FALHOU: %s\n", msg); fails++; }
    else printf("ok %s\n", msg);
}
static unsigned px(const mos_img_t *im, int x, int y) { return im->px[(size_t)y * (size_t)im->w + (size_t)x]; }
static int near_u(unsigned v, unsigned want, unsigned tol) {
    unsigned d = v > want ? v - want : want - v;
    return d <= tol;
}
static int flat_near(const mos_img_t *im, unsigned r, unsigned g, unsigned b, unsigned tol) {
    for (int y = 0; y < im->h; y++) for (int x = 0; x < im->w; x++) {
        unsigned p = px(im, x, y);
        if (!near_u((p >> 16) & 255, r, tol) || !near_u((p >> 8) & 255, g, tol) || !near_u(p & 255, b, tol) || (p >> 24) != 255)
            return 0;
    }
    return 1;
}
static void check_png_exact(const char *name, const unsigned char *b, size_t n, int w, int h, const unsigned *want) {
    mos_img_t im;
    int rc = mos_img_decode(b, n, &im);
    char buf[128];
    snprintf(buf, sizeof buf, "%s decodifica %dx%d", name, w, h);
    expect(rc == 0 && im.w == w && im.h == h, buf);
    if (rc == 0) {
        int ok = 1;
        for (int i = 0; i < w * h; i++) if (im.px[i] != want[i]) ok = 0;
        snprintf(buf, sizeof buf, "%s pixels", name);
        expect(ok, buf);
    }
    mos_img_free(&im);
}
int main(void) {
    expect(mos_img_uti(rgba_png, rgba_png_n) && !strcmp(mos_img_uti(rgba_png, rgba_png_n), "public.png"), "uti png");
    expect(mos_img_uti(flat_gray_jpg, flat_gray_jpg_n) && !strcmp(mos_img_uti(flat_gray_jpg, flat_gray_jpg_n), "public.jpeg"), "uti jpeg");
    expect(mos_img_uti((const unsigned char *)"nao", 3) == 0, "uti lixo");
    mos_img_t badim;
    expect(mos_img_decode((const unsigned char *)"GIF89a", 6, &badim) != 0, "recusa GIF");
    expect(mos_img_decode(bad_png, bad_png_n, &badim) != 0, "png com deflate quebrado");

    const unsigned rgba[] = { 0xFFFF0000u, 0x8000FF00u, 0xFF0000FFu, 0xFFFFFFFFu };
    check_png_exact("rgba", rgba_png, rgba_png_n, 2, 2, rgba);
    const unsigned gray[] = {
        0xFF0A0A0Au, 0xFF141414u, 0xFF1E1E1Eu, 0xFF282828u,
        0xFF0B0B0Bu, 0xFF161616u, 0xFF212121u, 0xFF2C2C2Cu
    };
    check_png_exact("gray filtro up", gray_png, gray_png_n, 4, 2, gray);
    const unsigned pal[] = { 0xFFFF0000u, 0x8000FF00u };
    check_png_exact("paleta tRNS", pal_png, pal_png_n, 2, 1, pal);
    unsigned adam[64];
    for (int i = 0; i < 64; i++) adam[i] = 0xFFFF0000u;
    check_png_exact("adam7", adam7_png, adam7_png_n, 8, 8, adam);
    const unsigned g16[] = { 0xFF808080u };
    check_png_exact("gray 16 bits (byte alto)", g16_png, g16_png_n, 1, 1, g16);

    struct { const char *name; const unsigned char *b; size_t n; int w, h; unsigned r, g, bch; } jpgs[] = {
        {"jpeg 4:2:0", flat_red_jpg, flat_red_jpg_n, 16, 16, 220, 30, 40},
        {"jpeg cinza", flat_gray_jpg, flat_gray_jpg_n, 8, 8, 180, 180, 180},
        {"jpeg progressivo", flat_blue_prog_jpg, flat_blue_prog_jpg_n, 16, 8, 20, 40, 200},
        {"jpeg 3x5", odd_jpg, odd_jpg_n, 3, 5, 10, 200, 30},
    };
    for (int i = 0; i < 4; i++) {
        mos_img_t im;
        int rc = mos_img_decode(jpgs[i].b, jpgs[i].n, &im);
        char buf[128];
        snprintf(buf, sizeof buf, "%s %dx%d", jpgs[i].name, jpgs[i].w, jpgs[i].h);
        expect(rc == 0 && im.w == jpgs[i].w && im.h == jpgs[i].h && im.has_alpha == 0, buf);
        snprintf(buf, sizeof buf, "%s pixels (tolerancia 2)", jpgs[i].name);
        expect(rc == 0 && flat_near(&im, jpgs[i].r, jpgs[i].g, jpgs[i].bch, 2), buf);
        mos_img_free(&im);
    }

    uint32_t src[6] = { 0xFFFF0000u, 0x8000FF00u, 0xFF0000FFu, 0xFF112233u, 0x01000000u, 0xFFFFFFFFu };
    uint8_t *enc = 0; size_t en = 0;
    expect(mos_img_encode_png(src, 3, 2, &enc, &en) == 0, "grava png");
    mos_img_t back;
    expect(mos_img_decode(enc, en, &back) == 0 && back.w == 3 && back.h == 2, "rele o png gravado");
    int same = back.px && memcmp(back.px, src, sizeof src) == 0;
    expect(same, "pixels do png gravado batem");
    free(enc);
    mos_img_free(&back);

    if (fails) { fprintf(stderr, "%d falhas\n", fails); return 1; }
    printf("tudo certo\n");
    return 0;
}
